import numpy as np
from PIL import Image
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
# make color legend blocks for dominant sample; print patch medians at 8x8 cells that are non-gray/blue
for y in range(0,192,8):
 vals=[]
 for x in range(0,256,8):
  b=im[y:y+8,x:x+8].reshape(-1,3).mean(0).astype(int)
  mx,mn=b.max(),b.min()
  if mx-mn<18: vals.append('gray')
  elif b[2]>b[0]*1.25: vals.append('blue')
  elif b[0]>b[1]*1.15: vals.append('pink')
  elif b[0]>b[2]*1.2: vals.append('red')
  else: vals.append('other')
 # group
 seg=[]; st=0
 for i in range(1,len(vals)+1):
  if i==len(vals) or vals[i]"'!=vals[st]:
   if i-st>=1: seg.append((st*8,i*8,vals[st]))
   st=i
 print(y, seg)
PY'

