  st=pr=xs[0]
  for x in xs[1:]:
   if x>pr+1:
    if pr-st>=1: seg.append((int(st),int(pr)))
    st=x
   pr=x
  if pr-st>=1: seg.append((int(st),int(pr)))
 print(y,seg)
